(function(){
 'use strict';
 const E=window.EDPEngine;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const nice=s=>s.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
 const names={F32:'Fit uncertainty',F33:'Quality questions',F41:'Comparing alternatives',F43:'Styling help',F45:'Value questions',F46:'Returns uncertainty',F51:'Decision overload'};
 function pname(p){return names[p]||(window.PROBLEM_META_EXT[p]?.name||p).replace(/^F\d+\s*/,'');}
 const scenarios={
  fit:{label:'Finding the right fit',persona:'size_anxious_new',quote:'“I like it. But which size should I buy?”',events:['search','category','product','chart','confirmFit','bag','returns','confirmReturns','checkout','delivery','order','care'],intro:'A shopper is considering a tuxedo for an upcoming event.'},
  compare:{label:'Choosing between options',persona:'comparison_shopper',quote:'“Is this the right one for the price?”',events:['search','category','product','compare','value','choose','confirmFit','bag','checkout','order','confirmStyle'],intro:'A returning shopper is comparing this tuxedo with other options.'},
  confident:{label:'Ready to buy',persona:'confident_buyer',quote:'“I know my size. Let me get on with it.”',events:['search','category','product','confirmFit','bag','checkout','order','care'],intro:'A confident shopper wants a short, direct path to checkout.'}
 };
 const actionLabels={search:'Search for wedding outfit',category:'Browse the collection',product:'Open the tuxedo',filter:'Filter the collection',priceFilter:'Change price filter',clearFilters:'Clear filters',saveItem:'Update wishlist',editItem:'Edit item',removeItem:'Remove item',deliveryOption:'Choose delivery',care:'Save care guidance',guidance:'Open page help',confirmHelp:'This answers my question',closeHelp:'Close help',chart:'Open size guide',returns:'Check returns',confirmFit:'Size 42 works for me',confirmReturns:'Returns are clear',compare:'Compare alternatives',value:'See materials & value',choose:'Choose this tuxedo',bag:'Add to bag',checkout:'Continue to checkout',wishlist:'Save to wishlist',styling:'Explore the outfit',material:'Inspect the material',confirmStyle:'This outfit works',confirmQuality:'Quality is clear',confirmValue:'Value is clear',delivery:'Check delivery',order:'Finish demo order'};
 let screen='experience',scenario='fit',events=[],cursor=0,playing=false,timer=null,selected=null,compare=false,exclude=[],cost=.06,version='v3',evaluation=null,evalPage='pdp',evalPolicy='adaptive',evalSeed=2026,evalN=240,evalSort='count',evalMessage='';
 const originals=[...document.body.children].filter(x=>!['SCRIPT','STYLE','LINK'].includes(x.tagName));
 const legacy=document.createElement('div');legacy.id='lab-legacy';legacy.hidden=true;originals.forEach(x=>legacy.appendChild(x));document.body.appendChild(legacy);
 document.body.className='edp-lab-body';
 const app=document.createElement('div');app.className='lab';app.id='edp-lab';document.body.insertBefore(app,legacy);
 const note=document.createElement('div');note.className='lab-legacy-note';note.textContent='Workbench · Original page builders and editable curves. Need scores and addressing coefficients are illustrative model assumptions. The original composer uses raw signals and six PDP slots; Experience adds confirmations, journey memory and an attention budget. “rem” is planned residual need; “cov” is supplied capacity.';legacy.prepend(note);
 // Clear the stale marketing counts and the unmeasured latency target in the original header.
 legacy.querySelectorAll('header p').forEach(p=>{if(p.textContent.includes('signals'))p.textContent='7 page types · Editable need detectors · Widget registries · Composition tools';});
 legacy.querySelectorAll('span,div').forEach(el=>{if(el.children.length===0&&el.textContent.includes('latency target:'))el.textContent='Local deterministic scoring · Model assumptions are editable';});
 function config(page,ver=version){const shapes={...(window.EDITED_SHAPES||window.PROBLEM_SHAPES),...window.PROBLEM_SHAPES_EXT};return {shapes:Object.fromEntries(window.PAGE_PROBLEMS[page].map(p=>[p,shapes[p]])),modules:page==='pdp'?(ver==='v3'?window.modulesV3:window.modulesV1):(ver==='v3'?window.PAGE_MODULES_V3[page]:window.PAGE_MODULES[page]),slots:window.PAGE_META[page].slots};}
 function initial(){return {feat:{...window.PERSONAS[scenarios[scenario].persona].vals},confirmed:{},page:'home',productId:'tuxedo',query:'wedding outfit',category:'All',under300:false,size:null,items:[],savedIds:[],delivery:'standard',careRead:false,panel:null,helpProblem:null,bag:false,saved:false,ordered:false,seen:[],dismissed:[],opened:null,action:null,messages:[],notice:scenarios[scenario].intro};}
 function state(){let s=initial();for(const ev of events.slice(0,cursor))s=reduce(s,ev);return s;}
 function reduce(prev,ev){const s=JSON.parse(JSON.stringify(prev));s.action=ev.action;
  if(ev.action==='search'){s.page='search';s.query=ev.value??'wedding outfit';s.panel=null;s.notice='Search results match the query. The shopper is looking for a wedding outfit.';}
  if(ev.action==='category'){s.page='plp';s.category=ev.value||'All';s.under300=false;s.panel=null;s.notice='The collection is ready to narrow by item type or price.';}
  if(ev.action==='product'){s.page='pdp';s.productId=ev.value||'tuxedo';s.size=s.items.find(x=>x.id===s.productId)?.size||null;s.panel=null;s.notice='Opened '+item(s).name+'. The product controls now act on this item.';}
  if(ev.action==='filter'){s.category=ev.value;s.feat.tab_switch=E.clamp(s.feat.tab_switch+.06);s.notice='Showing '+ev.value.toLowerCase()+' items in this collection.';}
  if(ev.action==='priceFilter'){s.under300=!s.under300;s.feat.price_dwell=E.clamp(s.feat.price_dwell+.08);s.notice=s.under300?'Showing items under €300.':'Price filter cleared.';}
  if(ev.action==='clearFilters'){s.category='All';s.under300=false;s.notice='All collection filters cleared.';}
  if(ev.action==='saveItem'){const id=ev.value;if(s.savedIds.includes(id))s.savedIds=s.savedIds.filter(x=>x!==id);else s.savedIds.push(id);s.saved=s.savedIds.length>0;s.feat.wishlist=E.clamp(s.feat.wishlist+.05);s.notice=s.savedIds.includes(id)?'Item saved to your demo wishlist.':'Item removed from your demo wishlist.';}
  if(ev.action==='editItem'){s.productId=ev.value;s.size=s.items.find(x=>x.id===ev.value)?.size||null;s.page='pdp';s.panel=null;s.notice='Choose a new size, then update the item using Add to bag.';}
  if(ev.action==='removeItem'){s.items=s.items.filter(x=>x.id!==ev.value);s.bag=s.items.length>0;s.notice='Item removed from your demo bag.';}
  if(ev.action==='deliveryOption'){s.delivery=ev.value;s.notice='Delivery option changed to '+ev.value+'.';}
  if(ev.action==='care'){s.careRead=true;s.confirmed.F62=.9;s.notice='Care guidance saved for this journey.';}
  if(ev.action==='closeHelp'){s.panel=null;s.opened=null;s.notice='Help closed. Previous confirmations are retained.';}
  if(['chart','returns','value','material','compare','styling','guidance'].includes(ev.action)){s.panel=ev.action;s.helpProblem=ev.problem||null;}
  if(ev.action==='guidance')s.notice='Opened help for this page. Tell the demo whether it answered your question.';
  if(ev.action==='confirmHelp'){if(!s.helpProblem&&ev.name){const mod=config(s.page).modules[ev.name];s.helpProblem=Object.entries(mod?.addr||{}).sort((a,b)=>b[1]-a[1])[0]?.[0];}if(s.helpProblem)s.confirmed[s.helpProblem]=.9;s.notice='The shopper confirmed that this help answered their question.';}
  if(ev.action==='page'){s.page=ev.value;s.panel=null;s.notice=`Opened ${window.PAGE_META[s.page].label}. Previous confirmations are retained.`;}
  if(ev.action==='signal'){s.feat[ev.key]=ev.value;s.notice=`Counterfactual: ${window.SIGNALS.find(x=>x.id===ev.key)?.name||ev.key} set to ${ev.value.toFixed(2)}.`;}
  if(ev.action==='size'){s.size=ev.value;s.notice=`Selected size ${s.size}. Selecting a size alone does not prove fit confidence.`;}
  if(ev.action==='chart'){s.feat.size_chart=E.clamp(s.feat.size_chart+.14);s.notice='The size guide was opened. Fit uncertainty is re-estimated from that evidence.';}
  if(ev.action==='returns'){s.feat.return_view=E.clamp(s.feat.return_view+.18);s.notice='Returns information was opened. The model treats this as a possible unresolved question.';}
  if(ev.action==='confirmFit'){s.size=s.size||'42';s.feat.size_conf=.95;s.confirmed.F32=.95;s.notice=`The shopper explicitly confirmed size ${s.size}. Estimated fit need falls; viewing a widget alone would not do this.`;}
  if(ev.action==='confirmReturns'){s.confirmed.F46=.95;s.notice='The shopper confirmed that returns are clear. This confirmation carries into the next page.';}
  if(ev.action==='compare'){s.feat.tab_switch=E.clamp(s.feat.tab_switch+.15);s.notice='The shopper compared alternatives. Comparison need has been re-estimated.';}
  if(ev.action==='value'){s.feat.price_dwell=E.clamp(s.feat.price_dwell+.12);s.notice='The shopper inspected materials and price. We still need their response to know whether it helped.';}
  if(ev.action==='choose'){s.confirmed.F41=.9;s.confirmed.F51=.6;s.notice='The shopper chose this product over the alternatives. Comparison need falls.';}
  if(ev.action==='bag'){if(!s.size){s.notice='Choose a size before adding this item to your bag.';s.panel='chart';}else{s.items=s.items.filter(x=>x.id!==s.productId);s.items.push({id:s.productId,size:s.size});s.bag=true;s.page='cart';s.panel=null;s.notice=item(s).name+' added to the demo bag. Earlier confirmations are retained.';}}
  if(ev.action==='checkout'&&s.items.length){s.page='checkout';s.panel=null;s.notice='Checkout opened. Existing confirmations are retained; no payment is collected.';}
  if(ev.action==='wishlist'){if(!s.savedIds.includes(s.productId))s.savedIds.push(s.productId);s.saved=true;s.feat.wishlist=E.clamp(s.feat.wishlist+.12);s.notice='Saved to the demo wishlist. Saving is evidence of interest, not proof of a decision.';}
  if(ev.action==='styling'){s.feat.style_stretch=E.clamp(s.feat.style_stretch+.15);s.notice='The shopper explored outfit ideas. Ask whether the suggestion works for them.';}
  if(ev.action==='material'){s.feat.zoom=E.clamp(s.feat.zoom+.15);s.notice='The shopper inspected material details. Quality questions remain an estimate.';}
  if(ev.action==='confirmStyle'){s.confirmed.F43=.9;s.confirmed.F61=.9;s.notice='The shopper confirmed that the outfit works.';}
  if(ev.action==='confirmQuality'){s.confirmed.F33=.9;s.confirmed.F31=.9;s.notice='The shopper confirmed that quality questions are answered.';}
  if(ev.action==='confirmValue'){s.confirmed.F45=.9;s.confirmed.F53=.9;s.notice='The shopper confirmed that the value is clear.';}
  if(ev.action==='delivery'){s.confirmed.F52=.8;s.notice='The shopper confirmed that delivery and checkout details are clear.';}
  if(ev.action==='order'&&s.items.length){s.ordered=true;s.page='post_purchase';s.panel=null;s.notice='Demo order completed. Styling and care needs can now be considered.';}
  if(ev.action==='dismiss'){s.dismissed.push(ev.name);s.notice=`${nice(ev.name)} dismissed for this journey.`;}
  if(ev.name&&ev.action!=='dismiss'){if(!s.seen.includes(ev.name))s.seen.push(ev.name);s.opened=ev.name;}if(ev.action.startsWith('confirm')||ev.action==='choose'||ev.action==='delivery'||ev.action==='dismiss'){s.opened=null;s.panel=null;}
  s.messages.push({label:ev.action==='page'?window.PAGE_META[ev.value].label:actionLabels[ev.action]||s.notice,notice:s.notice});return s;
 }
 function calculate(s,opts={}){const cfg=config(s.page,opts.version||version);const problems=E.detect(s.feat,cfg.shapes,s.confirmed);return E.compose({...cfg,problems,cost,excluded:[...exclude,...s.dismissed],seen:s.seen,...opts});}
 function dispatch(ev,manual=true){if(manual)pause();const before=state();events=events.slice(0,cursor);events.push(ev);cursor++;selected=null;const after=state();render();if(after.page!==before.page||ev.action==='reset')scrollToContent();else if(after.panel&&(after.panel!==before.panel||ev.action==='bag'||ev.name))scrollToContent('lab-help-anchor');}
 function pause(){playing=false;if(timer)clearTimeout(timer);timer=null;}
 function next(){const seq=scenarios[scenario].events,i=stepIndex();if(i>=seq.length){pause();render();return;}dispatch({action:seq[i],storyStep:i},false);if(stepIndex()>=seq.length)pause();if(playing)timer=setTimeout(next,4200);else render();}
 function reset(){pause();events=[];cursor=0;exclude=[];selected=null;compare=false;render();}
 function gotoScreen(value){pause();if(value==='workbench'){const s=state();Object.assign(window.featState,s.feat);for(const [k,v]of Object.entries(s.feat)){const el=document.getElementById(k),val=document.getElementById(k+'-val');if(el)el.value=v;if(val)val.textContent=v.toFixed(2);}window.clearActivePersona();if(window.useV3!==(version==='v3'))window.toggleVersion();else window.update();}screen=value;render();if(value==='evaluate'&&!evaluation)runEvaluation();}
 function stepIndex(){let i=0;const seq=scenarios[scenario].events;for(const e of events.slice(0,cursor)){if(e.storyStep!=null)i=Math.max(i,e.storyStep+1);else if(e.action===seq[i])i++;}return i;}
 const button=(label,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
 function header(){return `<header class="lab-header"><div><div class="eyebrow">Experience orchestration</div><h1>Help at the right moment.</h1></div><nav aria-label="Demo workspace">${['experience','workbench','evaluate'].map(x=>button(nice(x),'screen',`data-value="${x}" aria-pressed="${screen===x}"`)).join('')}</nav><span class="pill">Journey demo · revision 2</span></header>`;}
 function render(){const openDetails=[...app.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);const focus=document.activeElement;const focusKey=focus?.dataset?.focus;const focusAction=focus?.dataset?.action;const focusValue=focus?.dataset?.value;legacy.hidden=screen!=='workbench';app.innerHTML=header()+(screen==='experience'?experience():screen==='evaluate'?evaluateView():'');wire();app.querySelectorAll('details').forEach(d=>{if(openDetails.includes(d.querySelector('summary')?.textContent))d.open=true;});if(focusKey)app.querySelector(`[data-focus="${focusKey}"]`)?.focus({preventScroll:true});else if(focusAction)app.querySelector(`[data-action="${focusAction}"]${focusValue?`[data-value="${focusValue}"]`:""}`)?.focus({preventScroll:true});}
 function experience(){const s=state(),r=calculate(s),baseline=calculate(s,{policy:'independent',excluded:[]}),cfg=config(s.page);if(!r.page.some(e=>e.name===selected))selected=r.page[0]?.name||null;
  const previous=cursor?calculate(events.slice(0,cursor-1).reduce(reduce,initial())).page.map(e=>e.name):[];
  const seq=scenarios[scenario].events,step=stepIndex();return `<main class="lab-wrap"><section class="lab-story" aria-label="Guided shopper story"><div><div class="row spread"><span class="eyebrow">${esc(scenarios[scenario].label)}</span><span class="meta">${step} / ${seq.length} story events</span></div><p class="story-title">${esc(scenarios[scenario].quote)}</p><p class="muted">${step<seq.length?'Next: '+actionLabels[seq[step]]:'Journey complete. Explore another scenario or change a signal.'}</p><div class="lab-progress" aria-label="Story progress">${seq.map((_,i)=>`<span class="${i<step?'done':''}" style="display:block;height:5px;flex:1;border-radius:4px;background:${i<step?'var(--lab-accent)':'#33455e'}"></span>`).join('')}</div></div><div class="row">${button(playing?'Ⅱ Pause':'▶ Play','play',step>=seq.length?'disabled':'','primary')}${button('← Back','back',cursor===0?'disabled':'')}${button('Next event →','next',step>=seq.length?'disabled':'')}${button('Reset','reset')}</div></section>
   ${journeyStrip(s)}<div class="lab-toolbar"><label class="lab-inline"><span class="meta">Shopper</span><select data-change="scenario" aria-label="Shopper scenario">${Object.entries(scenarios).map(([k,v])=>`<option value="${k}" ${scenario===k?'selected':''}>${v.label}</option>`).join('')}</select></label><label class="lab-inline"><span class="meta">Page</span><select data-change="page" aria-label="Shopping page">${window.PAGES.map(p=>`<option value="${p}" ${s.page===p?'selected':''}>${window.PAGE_META[p].label}</option>`).join('')}</select></label><div class="row">${button('Compare pages','compare',`aria-pressed="${compare}"`)}${button('Open workbench','openWorkbench')}</div></div>
   <div class="lab-grid"><section class="lab-shop" aria-label="Interactive shopping page"><div class="lab-shopnav"><span class="lab-brand">BOSS</span><small>${window.PAGE_META[s.page].label} · ${s.items.length?s.items.length+' item'+(s.items.length===1?'':'s')+' in bag':'Demo shopping session'}</small></div><div class="lab-notice" role="status" aria-live="polite">${esc(s.notice)}</div>${pageContent(s)}<div class="lab-selected" id="lab-help-list"><div class="row spread"><h2>${s.page==='post_purchase'?'After your purchase':'Help for this moment'}</h2><small>${r.page.length} / ${cfg.slots} available placements</small></div><p style="font-size:14px;color:#5c6b7c;margin-top:5px">${r.page.length<cfg.slots?'Unused placements stay empty when expected help does not clear the attention cost.':'Select “Why this?” to inspect a decision.'}</p>${compare?comparison(r,baseline):''}<div class="lab-cards">${r.page.map(e=>widget(e,s,previous)).join('')}</div>${!r.page.length?'<div class="lab-empty gap"><h3>A clear path forward.</h3><p>No additional widget clears the current attention budget. The purchase controls remain available.</p></div>':''}</div></section><aside class="lab-aside"><div class="stack">${needs(r,s)}${inspector(r,s)}${timeline(s)}</div></aside></div></main>`;
 }
 const products=[
  {id:'tuxedo',name:'Slim-fit black wool tuxedo',brand:'BOSS',price:895,art:'tuxedo',kind:'Suit',fabric:'Wool',fit:'Slim'},
  {id:'shirt',name:'Cotton evening shirt',brand:'BOSS',price:129,art:'shirt',kind:'Shirt',fabric:'Cotton',fit:'Regular'},
  {id:'shoes',name:'Leather evening shoes',brand:'BOSS',price:249,art:'shoe',kind:'Shoes',fabric:'Leather',fit:'Regular'},
  {id:'bow',name:'Silk bow tie',brand:'BOSS',price:69,art:'bow',kind:'Accessory',fabric:'Silk',fit:'One size'}
 ];
 const item=s=>products.find(p=>p.id===s.productId)||products[0];
 const money=n=>'€'+n.toFixed(2);
 const art=p=>`<span class="journey-art" role="img" aria-label="${esc(p.name)}">${window.WidgetSVG[p.art]()}</span>`;
 function journeyStrip(s){return `<nav class="journey-strip" aria-label="Shopper journey pages">${window.PAGES.map((p,i)=>button(`${i+1} <span>${window.PAGE_META[p].label}</span>`,'navigate',`data-value="${p}" aria-current="${s.page===p?'page':'false'}" aria-pressed="${s.page===p}"`)).join('')}</nav>`;}
 function productTile(p,s){return `<article class="journey-product-tile">${button(art(p),'viewProduct',`data-value="${p.id}" aria-label="View ${esc(p.name)}"`,'journey-product-link')}<small>${p.kind} · ${p.fabric}</small><h3>${p.name}</h3><p>${money(p.price)}</p><div class="row">${button('View item','viewProduct',`data-value="${p.id}"`)}${button(s.savedIds.includes(p.id)?'Saved ✓':'Save','saveItem',`data-value="${p.id}" aria-pressed="${s.savedIds.includes(p.id)}"`)}</div></article>`;}
 function pageContent(s){return `<div id="lab-page-anchor" class="journey-page" data-page-view="${s.page}">${({home:homePage,search:searchPage,plp:categoryPage,pdp:detailPage,cart:cartPage,checkout:checkoutPage,post_purchase:afterPage})[s.page](s)}${feedbackPanel(s)}</div>`;}
 function homePage(s){return `<section class="journey-home"><div><small>Wedding season / The occasion edit</small><h2>Make an entrance.</h2><p>A considered outfit, from the first idea to the final detail.</p><div class="row gap">${button('Find my wedding outfit','shop','data-value="search"','primary')}${button('Browse tailoring','shop','data-value="category"')}</div></div>${art(products[0])}</section><section class="journey-section"><h3>Where would you like to start?</h3><div class="journey-category-grid gap">${[{name:'Suits & tuxedos',type:'Suit',art:'tuxedo'},{name:'Evening shirts',type:'Shirt',art:'shirt'},{name:'Shoes & finishing touches',type:'All',art:'shoe'}].map(c=>`<button data-action="browse" data-value="${c.type}">${window.WidgetSVG[c.art]()}<strong>${c.name}</strong><span>Explore collection →</span></button>`).join('')}</div></section>`;}
 function searchBox(s){return `<form class="journey-search" data-search-form><label for="journey-query">Search the collection</label><div class="row"><input id="journey-query" name="query" type="search" value="${esc(s.query)}" placeholder="Try tuxedo, shirt or leather" autocomplete="off"><button type="submit" class="primary">Search</button></div></form>`;}
 function searchMatches(s){const q=s.query.trim().toLowerCase();if(!q||/wedding|formal|outfit|evening/.test(q))return products;return products.filter(p=>`${p.name} ${p.kind} ${p.fabric}`.toLowerCase().includes(q));}
 function searchPage(s){const matches=searchMatches(s);return `<section class="journey-section">${searchBox(s)}<div class="row spread gap"><h2>Results for “${esc(s.query||'all items')}”</h2><span>${matches.length} demo items</span></div><p class="journey-subtitle">Browse the small demo collection, or refine it by category.</p><div class="row gap">${button('Refine in category','shop','data-value="category"')}${button('Show wedding outfit','searchPreset','data-value="wedding outfit"')}</div><div class="journey-products gap">${matches.map(p=>productTile(p,s)).join('')||`<div class="journey-empty"><h3>No matches in this demo collection.</h3><p>Try “tuxedo”, “shirt”, “leather”, or “wedding outfit”.</p>${button('Show all items','searchPreset','data-value=""')}</div>`}</div></section>`;}
 function categoryPage(s){const list=products.filter(p=>s.category==='All'||p.kind===s.category).filter(p=>!s.under300||p.price<300);return `<section class="journey-section"><small>Men / Occasionwear</small><h2 class="gap">Build the outfit.</h2><div class="journey-filters gap">${['All','Suit','Shirt','Shoes','Accessory'].map(t=>button(t==='All'?'All items':t,'filter',`data-value="${t}" aria-pressed="${s.category===t}"`)).join('')}${button('Under €300','priceFilter',`aria-pressed="${s.under300}"`)}</div><p class="journey-subtitle">${list.length} items · Filters update the visible collection and the session signals.</p><div class="journey-products">${list.map(p=>productTile(p,s)).join('')||`<div class="journey-empty"><h3>No items match these filters.</h3>${button('Clear filters','clearFilters')}</div>`}</div></section>`;}
 function detailPage(s){const p=item(s),sizes=p.id==='bow'?['One size']:p.id==='shoes'?['40','41','42','43','44']:['38','40','42','44','46','48'];return `<div class="lab-product">${art(p)}<div><small>Men / ${p.kind}</small><h2>${p.name}</h2><p class="price">${money(p.price)}</p><p class="journey-subtitle">${p.fabric} · ${p.fit} fit · Demo product</p><fieldset class="journey-sizes" id="journey-size"><legend>${s.size?'Selected size: '+s.size:'Choose a size'}</legend><div class="row">${sizes.map(z=>button(z,'size',`data-value="${z}" aria-pressed="${s.size===z}"`,'lab-size')).join('')}</div></fieldset><div class="lab-product-actions">${button('Add to bag','shop','data-value="bag"','primary')}${button(s.savedIds.includes(p.id)?'Saved ✓':'Save item','saveItem',`data-value="${p.id}" aria-pressed="${s.savedIds.includes(p.id)}"`)}</div><div class="lab-product-actions">${button('Size guide','shop','data-value="chart"')}${button('Returns','shop','data-value="returns"')}${button('Materials & value','shop','data-value="value"')}${button('Compare','shop','data-value="compare"')}</div></div></div>`;}
 function bagLines(s){return s.items.map(line=>{const p=products.find(x=>x.id===line.id);return `<article class="journey-bag-line">${art(p)}<div><h3>${p.name}</h3><p>Size ${esc(line.size)}</p><strong>${money(p.price)}</strong><div class="row gap">${button('Edit size','editItem',`data-value="${p.id}"`)}${button('Remove','removeItem',`data-value="${p.id}"`)}</div></div></article>`;}).join('');}
 function cartPage(s){const total=s.items.reduce((a,x)=>a+products.find(p=>p.id===x.id).price,0);return `<section class="journey-section"><small>Your selection</small><h2 class="gap">Shopping bag <span class="journey-count">${s.items.length}</span></h2>${s.items.length?`<div class="journey-cart-grid gap"><div>${bagLines(s)}</div><aside class="journey-summary"><h3>Order summary</h3><div class="row spread gap"><span>Items</span><strong>${money(total)}</strong></div><div class="row spread"><span>Delivery</span><span>Free · demo</span></div><hr><div class="row spread"><b>Total</b><b>${money(total)}</b></div><div class="stack gap">${button('Continue to checkout','shop','data-value="checkout"','primary')}${button('Check returns','shop','data-value="returns"')}${button('Continue shopping','shop','data-value="category"')}</div></aside></div>`:`<div class="journey-empty gap"><h3>Your bag is empty.</h3><p>Add an item from the collection to continue.</p>${button('Browse the collection','shop','data-value="category"','primary')}</div>`}</section>`;}
 function checkoutPage(s){const total=s.items.reduce((a,x)=>a+products.find(p=>p.id===x.id).price,0);return `<section class="journey-section"><small>Secure checkout · simulation</small><h2 class="gap">The final details.</h2>${s.items.length?`<div class="journey-cart-grid gap"><div><section class="journey-check-block"><h3>1. Delivery</h3><p>Demo address · Berlin, Germany</p><div class="row gap">${button('Standard · free','deliveryOption','data-value="standard" aria-pressed="'+(s.delivery==='standard')+'"')}${button('Pickup · free','deliveryOption','data-value="pickup" aria-pressed="'+(s.delivery==='pickup')+'"')}</div></section><section class="journey-check-block"><h3>2. Payment</h3><p>Demo payment method. No card details or payment will be collected.</p></section><section class="journey-check-block"><h3>3. Confirm the details</h3><p>${Object.keys(s.confirmed).length?'Your earlier confirmations are retained.':'Check delivery and returns before completing the demo.'}</p><div class="row gap">${button('Delivery details are clear','shop','data-value="delivery"')}${button('Review returns','shop','data-value="returns"')}</div></section></div><aside class="journey-summary"><h3>${s.items.length} item${s.items.length===1?'':'s'}</h3>${s.items.map(x=>`<p class="gap">${products.find(p=>p.id===x.id).name}<br><small>Size ${esc(x.size)}</small></p>`).join('')}<hr><div class="row spread"><b>Total</b><b>${money(total)}</b></div><div class="stack gap">${button('Finish demo order','shop','data-value="order"','primary')}${button('Back to bag','navigate','data-value="cart"')}</div><small>No purchase is made.</small></aside></div>`:`<div class="journey-empty gap"><p>Add an item before checking out.</p>${button('Browse collection','shop','data-value="category"')}</div>`}</section>`;}
 function afterPage(s){return `<section class="journey-section"><div class="journey-success"><span aria-hidden="true">✓</span><small>${s.ordered?'Demo order completed':'Post-purchase preview'}</small><h2>${s.ordered?'Your outfit is on its way.':'After the purchase.'}</h2><p>${s.ordered?'Your choices and confirmations remain part of this journey.':'Complete a demo order to see your selected items here.'}</p></div><div class="journey-post-grid gap"><section class="journey-check-block"><h3>Complete the look</h3><div class="journey-outfit-art">${window.WidgetSVG.shirt()}${window.WidgetSVG.bow()}${window.WidgetSVG.shoe()}</div><p>A shirt, bow tie and evening shoes for a formal outfit.</p><div class="row gap">${button('This outfit works','shop','data-value="confirmStyle"')}${button('Shop finishing touches','browse','data-value="Accessory"')}</div></section><section class="journey-check-block"><h3>Keep it looking good</h3><p>Check the garment’s care label before cleaning. A suitable hanger helps preserve its shape.</p>${button(s.careRead?'Care guidance saved ✓':'Save care guidance','care',`aria-pressed="${s.careRead}"`)}<h3 class="gap">Need anything else?</h3><div class="row gap">${button('Check returns','shop','data-value="returns"')}${button('Start another journey','reset')}</div></section></div></section>`;}
 function feedbackPanel(s){if(!s.panel)return '';const data={
  chart:{title:'Find your fit',text:'Example: size 42 corresponds to a 96–100 cm chest in this demo. Select a size, then confirm whether it works.',confirm:'confirmFit'},
  returns:{title:'Returns explained',text:'Demo policy: return an unworn item within 30 days. This fictional policy exists only for the walkthrough.',confirm:'confirmReturns'},
  value:{title:'Materials & value',text:`${item(s).name}: ${item(s).fabric.toLowerCase()}, ${item(s).fit.toLowerCase()} fit. Review the construction and price before deciding.`,confirm:'confirmValue'},
  material:{title:'A closer look',text:`This demo item uses ${item(s).fabric.toLowerCase()}. The material view is evidence of interest; it does not automatically resolve quality concerns.`,confirm:'confirmQuality'},
  compare:{title:'Compare your options',text:'Review the selected item against the other pieces in this small demo collection.',confirm:'choose'},
  styling:{title:'Putting the look together',text:'Consider the shirt, shoes and finishing touches together with the tuxedo.',confirm:'confirmStyle'},
  guidance:{title:'Help for this page',text:'Review this suggestion and tell the demo whether it answered your question.',confirm:'confirmHelp'}
 }[s.panel];if(!data)return '';return `<section class="journey-feedback" id="lab-help-anchor" aria-label="${data.title}"><div class="row spread"><h3>${data.title}</h3>${button('Close','closeHelp')}</div><p>${esc(data.text)}</p>${s.panel==='compare'?`<div class="journey-compare-grid">${products.slice(0,3).map(p=>`<div><strong>${p.name}</strong><p>${p.fabric} · ${money(p.price)}</p>${button('View item','viewProduct',`data-value="${p.id}"`)}</div>`).join('')}</div>`:''}${s.panel==='styling'?`<div class="journey-outfit-art">${window.WidgetSVG.shirt()}${window.WidgetSVG.shoe()}</div>`:''}<div class="row gap">${button(actionLabels[data.confirm]||'This helps','shop',`data-value="${data.confirm}"`,'primary')}${s.opened?button('Not useful','dismiss',`data-value="${s.opened}"`):''}</div></section>`;}

 function interactivePreview(html,name){return html.replace(/<button\b([^>]*)>([\s\S]*?)<\/button>/g,(_,attrs,body)=>{const label=body.replace(/<[^>]+>/g,'').trim().toLowerCase();let action='widgetControl',value=name,content='Open help';if(/size|fit/.test(label)){action='shop';value='chart';content=body;}else if(/return/.test(label)){action='shop';value='returns';content=body;}else if(/compar/.test(label)){action='shop';value='compare';content=body;}else if(/wishlist|save/.test(label)){action='saveItem';value=state().productId;content='Save item';}attrs=attrs.replace(/\s(?:onclick|disabled|data-action|data-value|type)=(?:"[^"]*"|'[^']*')/g,'').replace(/\sdisabled\b/g,'');return `<button${attrs} type="button" data-action="${action}" data-value="${value}">${content}</button>`;});}
 function widgetAction(e){const p=Object.entries(e.mod.addr||{}).sort((a,b)=>b[1]-a[1])[0]?.[0];return ({F32:'confirmFit',F46:'confirmReturns',F41:'choose',F45:'confirmValue',F53:'confirmValue',F33:'confirmQuality',F31:'confirmQuality',F43:'confirmStyle',F61:'confirmStyle',F52:'delivery',F51:'choose'})[p]||'confirmHelp';}
 function widget(e,s,previous){const addressed=Object.entries(e.mod.addr||{}).filter(([p])=>e.before[p]>0).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([p])=>pname(p)).join(' · ');const act=widgetAction(e),renderer=s.page==='pdp'?window.WidgetRenderers[e.name]:window.PageWidgets[s.page]?.[e.name];return `<article class="lab-card ${!previous.includes(e.name)?'fresh':''} ${selected===e.name?'focused':''}"><div class="row spread"><small>Placement ${e.slot+1}</small><small>${!previous.includes(e.name)&&cursor?'New choice':''}</small></div><h3>${nice(e.name)}</h3><p>${addressed||'General shopping assistance'}</p><small>Expected help: ${e.gain.toFixed(2)} need units</small><div class="card-foot">${button('Why this?','inspect',`data-value="${e.name}" aria-pressed="${selected===e.name}"`)}${button('Open help','openHelp',`data-value="${e.name}"`)}${button('Dismiss','dismiss',`data-value="${e.name}"`)}</div>${s.action==='help'&&s.help===e.name?'':''}${s.seen.includes(e.name)?`<div class="lab-preview"><p>Was this helpful?</p>${button(actionLabels[act],'shop',`data-value="${act}" data-name="${e.name}"`)}</div>`:''}${renderer?`<details class="lab-preview"><summary>Full widget · interactive</summary><div>${interactivePreview(renderer({entry:e,mod:e.mod,slotIdx:e.slot,problems:rProblems(s),coverage:{}}),e.name)}</div><small>Controls update this demo journey.</small></details>`:''}</article>`;}
 function rProblems(s){return E.detect(s.feat,config(s.page).shapes,s.confirmed);}
 function comparison(r,b){const set=new Set(b.page.map(x=>x.name));return `<div class="lab-diff"><div><b>Personalized one-pass ranking</b><ol>${b.page.map(e=>`<li>${nice(e.name)}</li>`).join('')}</ol><small>${(b.coverageRate*100).toFixed(0)}% expected coverage · ${b.page.length} widgets</small></div><div><b>Adaptive + attention budget</b><ol>${r.page.map(e=>`<li class="${set.has(e.name)?'':'added'}">${nice(e.name)}</li>`).join('')}</ol><small>${(r.coverageRate*100).toFixed(0)}% expected coverage · ${r.page.length} widgets</small></div></div>`;}
 function needs(r,s){return `<section class="lab-panel"><div class="row spread"><h2>Estimated needs</h2><span class="pill">Model output</span></div><p>Bars show current estimates. Selecting help does not change them; shopper evidence does.</p>${Object.entries(r.problems).sort((a,b)=>b[1]-a[1]).map(([p,v])=>`<div class="lab-need"><div class="row spread"><span>${pname(p)}</span><span>${v.toFixed(2)}${s.confirmed[p]?' ✓':''}</span></div><div class="lab-track"><span style="width:${v*100}%"></span></div></div>`).join('')}<div class="lab-statrow"><div class="lab-stat"><strong>${(r.coverageRate*100).toFixed(0)}%</strong><small>Expected need coverage</small></div><div class="lab-stat"><strong>${E.sum(r.remaining).toFixed(2)}</strong><small>Planned residual need</small></div><div class="lab-stat"><strong>${r.page.length}</strong><small>Help placements</small></div></div><small>✓ Explicit confirmation received. Its effect size remains a model assumption.</small><details class="lab-details"><summary>Attention budget & model version</summary><label class="stack gap">Minimum expected help per widget: ${cost.toFixed(2)}<input type="range" min="0" max="0.3" step="0.01" value="${cost}" data-change="cost" data-focus="cost" aria-label="Attention cost per widget"></label><label class="row gap">Widget weights<select data-change="version" aria-label="Widget model version"><option value="v1" ${version==='v1'?'selected':''}>Original v1</option><option value="v3" ${version==='v3'?'selected':''}>Edited v3</option></select></label><p class="gap">Capacity is discounted by position. Displayed help is only expected coverage, never measured customer resolution.</p>${exclude.length?button('Restore excluded widgets','restore'):''}</details></section>`;}
 function inspector(r,s){const e=r.page.find(e=>e.name===selected);if(!e)return `<section class="lab-panel lab-inspector" id="lab-inspector"><h2>Decision inspector</h2><p>${r.log[0]?.reason||'No widget is currently selected.'}</p></section>`;const other=e.candidates.find(c=>c.name!==e.name),contributions=[...e.contributions,...(e.repeatPenalty?[{label:'Already opened in journey',value:-e.repeatPenalty}]:[])];const max=Math.max(.01,...contributions.map(t=>Math.abs(t.value)));const primary=Object.entries(e.mod.addr||{}).sort((a,b)=>b[1]*(e.before[b[0]]||0)-a[1]*(e.before[a[0]]||0))[0]?.[0];const shape=config(s.page).shapes[primary]?.[0];const changed=calculate(s,{excluded:[...exclude,...s.dismissed,e.name]});const replacements=changed.page.filter(x=>!r.page.some(y=>y.name===x.name)).map(x=>nice(x.name));return `<section class="lab-panel lab-inspector" id="lab-inspector"><div class="eyebrow">Why this widget?</div><h2 style="margin-top:5px">${nice(e.name)}</h2><p>Highest eligible score at placement ${e.slot+1}: <b style="color:white">${e.score.toFixed(3)}</b>. Expected help ${e.gain.toFixed(2)} clears the ${cost.toFixed(2)} attention cost.</p>${other?`<p class="gap">Runner-up: <b>${nice(other.name)}</b> (${other.score.toFixed(3)}). Margin ${(e.score-other.score).toFixed(3)}.</p>`:''}<div class="gap">${contributions.filter(t=>Math.abs(t.value)>.0001).map(t=>`<div class="lab-term"><div>${t.label}${t.problem?' · '+pname(t.problem):''}<div class="lab-track ${t.value<0?'negative':''}"><span style="width:${Math.abs(t.value)/max*100}%"></span></div></div><span>${t.value>=0?'+':''}${t.value.toFixed(3)}</span></div>`).join('')}</div>${shape?curve(shape,s,primary):''}<details class="lab-details"><summary>What if this widget were unavailable?</summary><p class="gap">${replacements.length?'New selection: '+replacements.join(', '):'The remaining eligible widgets would stay; the page may use fewer placements.'}</p><p>Expected coverage: ${(r.coverageRate*100).toFixed(0)}% → ${(changed.coverageRate*100).toFixed(0)}%.</p><div class="gap">${button('Try excluding this widget','exclude',`data-value="${e.name}"`)}</div></details></section>`;}
 function curve(c,s,p){const x=s.feat[c.signal],v=E.pwl(x,c);const pts=c.bps.map((b,i)=>`${30+b*250},${114-c.vals[i]*90}`).join(' ');return `<div class="lab-details"><h3>${pname(p)}: one signal’s curve</h3><svg class="lab-curve" viewBox="0 0 310 145" role="img" aria-label="${esc(c.title)} shape function with current value ${x.toFixed(2)}"><path d="M30 20V114H285" fill="none" stroke="#52677f"/><line x1="30" y1="69" x2="285" y2="69" stroke="#283e55"/><polyline points="${pts}" fill="none" stroke="#65edc1" stroke-width="2.5"/><line x1="${30+x*250}" y1="20" x2="${30+x*250}" y2="114" stroke="#85bfff" stroke-dasharray="3 4"/><circle cx="${30+x*250}" cy="${114-v*90}" r="5" fill="#85bfff"/><text x="26" y="134">0</text><text x="278" y="134">1</text><text x="9" y="28">1</text><text x="9" y="118">0</text></svg><label for="lab-signal" style="font-size:14px">${esc(c.title)} · ${x.toFixed(2)}</label><input id="lab-signal" type="range" min="0" max="1" step="0.01" value="${x}" data-change="signal" data-key="${c.signal}" data-focus="signal" aria-label="${esc(c.title)} counterfactual"><p>Drag to change this signal. Other signals and explicit confirmations also affect the estimate.</p></div>`;}
 function timeline(s){return `<section class="lab-panel"><h2>Journey memory</h2><p>${s.seen.length} help widgets opened · ${Object.keys(s.confirmed).length} needs explicitly confirmed.</p><ol class="lab-trace">${s.messages.slice(-5).map(m=>`<li>${esc(m.label)}</li>`).join('')||'<li>The shopper arrived on the Home page.</li>'}</ol><small>Back and Reset restore earlier signals and confirmations. This session stays in this tab.</small></section>`;}
 function runEvaluation(){pause();evalMessage='Running reproducible sessions…';render();setTimeout(()=>{try{const cfg=config(evalPage,'v3');evaluation=E.evaluate({...cfg,modulesV1:config(evalPage,'v1').modules,personas:window.PERSONAS,n:evalN,seed:evalSeed,cost});evaluation.page=evalPage;evalMessage=`Completed ${evalN} sessions per policy · seed ${evalSeed}.`; }catch(err){evalMessage='Evaluation failed: '+err.message;}render();},30);}
 function evaluateView(){const data=evaluation?.page===evalPage?evaluation:null,out=data?.output[evalPolicy];return `<main class="lab-wrap"><div class="row spread"><div><div class="eyebrow">Reproducible model evaluation</div><h1 style="margin-top:7px">Does the composition help?</h1><p class="muted gap">Compare expected need coverage, remaining need and page length on the same simulated shoppers.</p></div>${button('Run evaluation','run','','primary')}</div><div class="lab-toolbar"><label class="lab-inline">Page<select data-change="evalPage">${window.PAGES.map(p=>`<option value="${p}" ${evalPage===p?'selected':''}>${window.PAGE_META[p].label}</option>`).join('')}</select></label><label class="lab-inline">Sessions<input type="number" min="80" max="2000" step="80" value="${evalN}" data-change="evalN" aria-label="Number of simulated sessions"></label><label class="lab-inline">Seed<input type="number" min="0" max="999999" value="${evalSeed}" data-change="evalSeed" aria-label="Simulation seed"></label><span class="pill">Attention cost ${cost.toFixed(2)} · v3 weights except original-weight policy</span></div><div class="lab-status" role="status">${esc(evalMessage)}</div>${data?`<section class="lab-panel"><div class="lab-tablewrap"><table><thead><tr><th>Policy</th><th class="num">Expected coverage</th><th class="num">Residual need</th><th class="num">Widgets / page</th><th class="num">Net modeled utility</th></tr></thead><tbody>${Object.values(data.output).map(r=>`<tr class="${r.policy===evalPolicy?'active':''}"><td>${button(r.label,'evalPolicy',`data-value="${r.policy}" aria-pressed="${r.policy===evalPolicy}"`)}</td><td class="num">${(r.coverageRate*100).toFixed(1)}%</td><td class="num">${r.avgResidual.toFixed(3)}</td><td class="num">${r.avgWidgets.toFixed(2)}</td><td class="num">${r.netUtility.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="gap">Net modeled utility = expected reduction in need − attention cost × widget count. It is not revenue, conversion or an observed customer outcome.</p></section>${out?analytics(out):''}`:'<div class="lab-panel"><p>Choose a page and run the same seeded sessions through every policy.</p></div>'}<details class="lab-assumptions" open><summary>What this evaluation can and cannot establish</summary><ul><li>All policies see the same eight preset profiles with small, seeded signal perturbations. This is a synthetic population.</li><li>Expected coverage = 1 − total residual need / total initial need. It is bounded between 0% and 100%; zero-need sessions add no denominator mass.</li><li>Widget selection counts and positions below come from actual composition logs. There are no fabricated traffic totals, CTRs, add-to-bag estimates or calendar trends.</li><li>The fixed page is calibrated on the eight unperturbed preset means, then evaluated on perturbed sessions. It is a useful demo control, not an independently trained production baseline.</li><li>One-pass ranking scores widgets once; adaptive selection re-scores after each placement and stops when marginal expected help is too small.</li><li>Need curves, widget effectiveness, confirmation effects, position discount and attention costs are assumptions. Noisy and exploratory policies do not learn; this demo does not claim Thompson sampling or a submodular approximation guarantee.</li><li>Greater modeled coverage does not establish greater real-world conversion. That requires outcome data and an independent evaluation.</li></ul></details></main>`;}
 function analytics(out){const rows=Object.keys(config(evalPage,'v3').modules).map(name=>({name,count:out.counts[name]||0,slots:out.positions[name]||[]})).sort((a,b)=>evalSort==='name'?a.name.localeCompare(b.name):b.count-a.count||a.name.localeCompare(b.name));return `<div class="lab-grid gap" ><section class="lab-panel"><div class="row spread"><h2>Logged widget selections</h2><label class="meta">Sort <select data-change="evalSort"><option value="count" ${evalSort==='count'?'selected':''}>Selections</option><option value="name" ${evalSort==='name'?'selected':''}>Widget name</option></select></label></div><p>${out.label} · ${out.n} simulated sessions. Counts measure selection, not whether someone viewed the widget.</p><div class="lab-tablewrap gap"><table><thead><tr><th>Widget</th><th class="num">Selected</th><th class="num">Session share</th><th>Positions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${nice(r.name)}</td><td class="num">${r.count}</td><td class="num">${(r.count/out.n*100).toFixed(1)}%</td><td><span class="meta">${r.slots.length?r.slots.map((n,i)=>`${i+1}: ${n}`).join(' · '):'—'}</span></td></tr>`).join('')}</tbody></table></div></section><section class="lab-panel"><h2>Results by shopper profile</h2><div class="lab-tablewrap"><table><thead><tr><th>Profile</th><th class="num">Coverage</th><th class="num">Widgets</th></tr></thead><tbody>${Object.entries(out.perPersona).map(([p,v])=>`<tr><td>${window.PERSONAS[p].label}</td><td class="num">${(v.initial?v.resolved/v.initial*100:0).toFixed(1)}%</td><td class="num">${(v.widgets/v.sessions).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><details class="lab-details"><summary>Inspect a logged session</summary>${out.logs[0]?`<p class="gap">Session 1 · ${window.PERSONAS[out.logs[0].persona].label}</p><ol class="lab-trace">${out.logs[0].result.page.map(e=>`<li>${nice(e.name)} · score ${e.score.toFixed(3)} · expected help ${e.gain.toFixed(3)}</li>`).join('')}</ol>`:''}</details></section></div>`;}
 function scrollToContent(id='lab-page-anchor'){
  const target=document.getElementById(id);if(!target)return;
  const bar=app.querySelector('.lab-story'),height=bar?.getBoundingClientRect().height||0;
  const top=target.getBoundingClientRect().top+window.scrollY-height-18;
  window.scrollTo({top:Math.max(0,top),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 }
 function handleAction(a,v,name){
  if(a==='screen')return gotoScreen(v);
  if(a==='openWorkbench')return gotoScreen('workbench');
  if(a==='play'){if(playing){pause();render();}else{playing=true;next();}return;}
  if(a==='next'){pause();next();return;}
  if(a==='back'){pause();cursor=Math.max(0,cursor-1);selected=null;render();scrollToContent();return;}
  if(a==='reset'){reset();scrollToContent();return;}
  if(a==='compare'){compare=!compare;render();scrollToContent('lab-help-list');return;}
  if(a==='navigate'){dispatch({action:'page',value:v});scrollToContent();return;}
  if(a==='viewProduct'){dispatch({action:'product',value:v});return;}
  if(a==='browse'){dispatch({action:'category',value:v});return;}
  if(a==='searchPreset'){dispatch({action:'search',value:v});return;}
  if(a==='filter'){dispatch({action:'filter',value:v});return;}
  if(a==='priceFilter'){dispatch({action:'priceFilter'});return;}
  if(a==='clearFilters'){dispatch({action:'clearFilters'});return;}
  if(a==='size'){dispatch({action:'size',value:v});return;}
  if(a==='saveItem'){dispatch({action:'saveItem',value:v});return;}
  if(a==='editItem'){dispatch({action:'editItem',value:v});return;}
  if(a==='removeItem'){dispatch({action:'removeItem',value:v});return;}
  if(a==='deliveryOption'){dispatch({action:'deliveryOption',value:v});return;}
  if(a==='care'){dispatch({action:'care'});return;}
  if(a==='closeHelp'){dispatch({action:'closeHelp'});return;}
  if(a==='shop'){dispatch({action:v,name});return;}
  if(a==='inspect'){pause();selected=v;render();scrollToContent('lab-inspector');return;}
  if(a==='openHelp'||a==='widgetControl'){
   const mod=config(state().page).modules[v];if(!mod)return;
   const primary=Object.entries(mod.addr||{}).sort((x,y)=>y[1]-x[1])[0]?.[0];
   const action=({F32:'chart',F46:'returns',F41:'compare',F45:'value',F33:'material',F43:'styling',F61:'styling'})[primary]||'guidance';
   dispatch({action,name:v,problem:primary});return;
  }
  if(a==='confirmWidget'){dispatch({action:'confirmHelp',name:v});return;}
  if(a==='dismiss'){dispatch({action:'dismiss',name:v});return;}
  if(a==='exclude'){pause();exclude.push(v);render();return;}
  if(a==='restore'){exclude=[];render();return;}
  if(a==='run')return runEvaluation();
  if(a==='evalPolicy'){evalPolicy=v;render();return;}
 }
 function handleChange(a,v,key){
  if(a==='scenario'){scenario=v;reset();scrollToContent();}
  if(a==='page'){dispatch({action:'page',value:v});scrollToContent();}
  if(a==='signal')dispatch({action:'signal',key,value:Number(v)});
  if(a==='cost'){pause();cost=Number(v);evaluation=null;render();}
  if(a==='version'){version=v;render();}
  if(a==='evalPage'){evalPage=v;evaluation=null;runEvaluation();}
  if(a==='evalSeed'){evalSeed=Math.max(0,Math.min(999999,Math.floor(Number(v)||0)));evaluation=null;evalMessage='Settings changed. Run evaluation to refresh results.';render();}
  if(a==='evalN'){evalN=Math.max(80,Math.min(2000,Math.floor(Number(v)||240)));evaluation=null;evalMessage='Settings changed. Run evaluation to refresh results.';render();}
  if(a==='evalSort'){evalSort=v;render();}
 }
 function wire(){
  // The root is stable across renders: each event is handled once.
  if(app.dataset.wired)return;app.dataset.wired='true';
  app.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||!app.contains(el)||el.disabled)return;handleAction(el.dataset.action,el.dataset.value,el.dataset.name);});
  app.addEventListener('change',event=>{const el=event.target.closest('[data-change]');if(el)handleChange(el.dataset.change,el.value,el.dataset.key);});
  app.addEventListener('submit',event=>{const form=event.target.closest('[data-search-form]');if(!form)return;event.preventDefault();dispatch({action:'search',value:form.querySelector('input[name="query"]').value});});
 }

 // All legacy analytics/policy entry points use the same logged evaluation surface.
 const oldSwitch=window.switchTab;window.switchTab=function(tab){if(tab==='analytics'||tab==='policies'){evalPage=window.getCurrentPage?.()||'pdp';evaluation=null;gotoScreen('evaluate');return;}return oldSwitch(tab);};
 window.psBuildAnalyticsSection=function(){const presets=window.allPresets(),cfg=config('pdp',window.useV3?'v3':'v1');return `<section class="lab lab-panel gap"><h2>Preset composition check</h2><p>Expected need coverage under the original six-slot composer. These are model estimates, not observed outcomes.</p><div class="lab-tablewrap"><table><thead><tr><th>Preset</th><th>Selected widgets</th><th>Expected coverage</th><th>Residual need</th></tr></thead><tbody>${Object.values(presets).map(p=>{const r=window.compose(p.vals,cfg.modules,6),mass=E.sum(r.problems),rem=E.sum(r.remaining);return `<tr><td>${esc(p.label)}</td><td>${r.page.slice(0,3).map(e=>nice(e.name)).join(', ')}</td><td>${(mass?(1-rem/mass)*100:0).toFixed(1)}%</td><td>${rem.toFixed(3)}</td></tr>`;}).join('')}</tbody></table></div></section>`;};
 window.renderAnalytics=()=>gotoScreen('evaluate');window.renderPolicies=()=>gotoScreen('evaluate');
 window.addEventListener('keydown',ev=>{if(screen!=='experience'||['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY'].includes(ev.target.tagName))return;if(ev.code==='Space'){ev.preventDefault();if(playing){pause();render();}else{playing=true;next();}}if(ev.key==='ArrowRight'){pause();next();}if(ev.key==='ArrowLeft'){pause();cursor=Math.max(0,cursor-1);render();}});
 window.addEventListener('pagehide',pause);
 window.EDPLab={config,getState:state,calculate,reduce,initial,dispatch,reset,handleAction,handleChange,next,stepIndex,pageContent,getEvents:()=>events.slice(0,cursor)};
 render();
})();
